 // src/components/Questions/EditQuestionForm.js

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getQuestionById, updateQuestion } from '../../services/api';
import './EditQuestionForm.css';

function EditQuestionForm() {
  const { id } = useParams();
  const navigate = useNavigate();

  const [title, setTitle] = useState('');
  const [text, setText] = useState('');
  const [tagString, setTagString] = useState('');
  const [image, setImage] = useState(null);

  const [userId, setUserId] = useState(null);

  useEffect(() => {
    const storedId = localStorage.getItem('userId');
    if (storedId) setUserId(Number(storedId));

    getQuestionById(id)
      .then(q => {
        setTitle(q.title);
        setText(q.text);
        setTagString((q.questionTags || []).map(t => t.tag.name).join(', '));
      })
      .catch(() => alert('Nu am putut încărca întrebarea'));
  }, [id]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append('title', title);
    formData.append('text', text);
    formData.append('user.id', userId);
    if (tagString) {
      tagString.split(',').map(t => t.trim()).forEach(tag => formData.append('tagNames', tag));
    }
    if (image) {
      formData.append('image', image);
    }

    try {
      await updateQuestion(id, formData);
      alert('Întrebarea a fost actualizată!');
      navigate(`/questions/${id}`);
    } catch (err) {
      alert('Eroare la actualizare: ' + err.message);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="edit-question-form">
      <h2>Editează întrebarea</h2>
      <input
        type="text"
        placeholder="Titlu întrebare"
        value={title}
        onChange={(e) => setTitle(e.target.value)}
        required
      />
      <textarea
        placeholder="Text întrebare"
        value={text}
        onChange={(e) => setText(e.target.value)}
        required
      />
      <input
        type="text"
        placeholder="Etichete (ex: Java, Spring)"
        value={tagString}
        onChange={(e) => setTagString(e.target.value)}
      />
      <input
        type="file"
        accept="image/*"
        onChange={(e) => setImage(e.target.files[0])}
      />
      <button type="submit">Salvează modificările</button>
    </form>
  );
}

export default EditQuestionForm;
